STUDY_QUESTIONS={}
for topic, rows in DATA.items():
    questions=[]
    for i,(question,correct,a,b,c,why) in enumerate(rows):
        options=[correct,a,b,c]; order=list(range(4));random.Random(930+i+len(topic)).shuffle(order)
        questions.append({'q':question,'a':[options[n] for n in order],'correct':order.index(0),'why':why})
    STUDY_QUESTIONS[topic]=questions
